import { RecordId } from "kernel/v1/record_id.skir";

// Service is the registration service's canonical record for one issued service identity.
// Its lifecycle has independent dimensions. Identity is durable, registration is a temporary unbound lease,
// organization is the user controlled binding, and state is liveness reported by the service registrar.
// Binding consumes the valid registration lease and clears registration. Unbinding clears both organization and
// registration. Revision is owned by the registration service and advances for mutable service metadata changes,
// allowing organization clients to perform compare and set updates without treating liveness as a rename conflict.
struct Service {
  service_id: RecordId;
  revision: int64;
  name: string;
  role: ServiceRole;
  created_at: timestamp;
  organization: RecordId?;
  registration: ServiceRegistration?;
  state: ServiceState?;
}

// The issued role is part of identity and is validated before the service account and record are created.
// A host role is required before the registration service accepts host execution registration.
enum ServiceRole {
  host: struct {
    version: string;
  } = 1;
  custom: struct {
    name: string;
    version: string;
  } = 2;
}

// Liveness state written by heartbeat and orderly shutdown notifications. Online means a heartbeat was accepted;
// offline means an orderly shutdown was accepted. Neither state changes organization binding or grants authority.
enum ServiceStatus {
  online;
  offline;
}

// A service registrar owns these observations. last_seen records when the registration service accepted the latest
// liveness notification. A missing or delayed notification is not the same protocol event as an accepted shutdown.
struct ServiceState {
  status: ServiceStatus;
  last_seen: timestamp;
}

// Temporary capability for binding an unbound service to an organization. EnsureRegistrationLease creates or renews it
// only while the service is unbound. BindService requires an unexpired token, then consumes it atomically with the
// organization binding, so the lease cannot substitute for an established binding or durable identity.
struct ServiceRegistration {
  token: string;
  expires_at: timestamp;
}

modules.service/v1/registration.skir:
import { InternalError } from "kernel/v1/errors.skir";
import { ServiceRole } from "service/v1/service.skir";

// Completes the operator mediated transition from an issued, unbound service to an organization bound service.
// The registration token is a temporary bearer capability. The registration service validates its expiry and
// atomically consumes it while writing the organization binding. This operation is user scoped
// and does not issue or replace service identity credentials.
method BindService(
  struct {
    registration_token: string;
  }
): enum {
  internal_error: InternalError;

  success: struct {
    service_id: string;
    service_name: string?;
    service_role: ServiceRole;
  };

  invalid_registration_token_error: struct {};
  organization_not_found_error: struct {};
} = 304691;

// Authoritative binding transition delivered to the service registrar after BindService commits.
// It carries organization context only. Receipt means binding changed, not that the service has proved liveness;
// the registrar must still establish authenticated messaging and send heartbeats.
struct ServiceBoundNotification {
  organization_id: string;
  organization_name: string?;
}

// Removes the organization binding for a service owned by the addressed organization.
// The registration service also clears any registration lease and publishes fresh organization views. The service
// identity remains intact, so a later binding uses a newly observed lease rather than reviving the old one.
method UnbindService(
  struct {
    service_id: string;
  }
): enum {
  internal_error: InternalError;

  success: struct {};

  service_not_found_error: struct {};
} = 950343;

modules.service/v1/lifecycle.skir:
// Sent by a service registrar while its authenticated messaging runtime is ready.
// The registration service records the service as online and refreshes last_seen. It emits an organization
// service update only when the service is organization bound. This is liveness, not identity or binding proof.
struct ServiceHeartbeatNotification {}

// Sent during orderly registrar shutdown before its messaging runtime is closed.
// The registration service records the service as offline. Missing shutdown is therefore distinguishable from
// an explicit offline transition, and consumers can use last_seen to assess stale liveness.
struct ServiceShutdownNotification {}

